<script setup lang="ts">
/**
 * Title, description and actions at the top of a working page (`design/components/page-header.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/page-header.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { cloneVNode } from 'vue'

import { definedProps, slottedElements } from '@polymorph/vue'
import styles from '@polymorph/recipes/structure/page-header.module.css'
import Inline from '../layout/Inline.vue'

export interface PageHeaderProps {
  description?: string
  title: string
}

defineOptions({ name: 'PageHeader', inheritAttrs: false })

defineProps<PageHeaderProps>()
defineSlots<{
  actions?: (props: Record<string, never>) => unknown
  titleEdit?: (props: Record<string, never>) => unknown
}>()
</script>

<template>
  <header :class="styles.header" data-member="page-header">
    <!-- text -->
    <div :class="styles.text">
      <!-- titleRow -->
      <div v-if="$slots.titleEdit" :class="styles.titleRow">
        <!-- title -->
        <h1 :class="styles.title">
          {{ title }}
        </h1>
        <!-- titleEdit -->
        <div :class="styles.titleEdit">
          <template v-for="(node, at) in slottedElements($slots.titleEdit)" :key="at">
            <component :is="cloneVNode(node, definedProps({ valueHidden: true }))" />
          </template>
        </div>
      </div>
      <!-- title -->
      <h1 v-else :class="styles.title">
        {{ title }}
      </h1>
      <!-- description -->
      <p v-if="description !== undefined" :class="styles.description">
        {{ description }}
      </p>
    </div>
    <Inline v-if="$slots.actions" :gap="3" :wrap="true">
      <slot name="actions" />
    </Inline>
  </header>
</template>
